import{z as i,x as p,o as B,c as A,q as r,j as s,D as e,d as n,s as o,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"流水线异常","description":"","frontmatter":{"title":"流水线异常","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pipeline-exception.md","filePath":"cs/pipeline-exception.md","lastUpdated":1791413859000}'),d={name:"cs/pipeline-exception.md"};function C(m,a,P,D,F,u){const t=p("Mermaid");return B(),A("div",null,[a[2]||(a[2]=r('<h1 id="流水线异常" tabindex="-1">流水线异常 <a class="header-anchor" href="#流水线异常" aria-label="Permalink to &quot;流水线异常&quot;">​</a></h1><div class="epigraph"><p>流水线里同时活着好几条指令时，异常仍必须看起来像发生在某条指令的边界上。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V)；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/tournament-predict">上一课</a>让 IF 按预测取指，错了就冲刷。<a href="/cs/exception-interrupt-entry">异常与中断入口</a>和<a href="/cs/privilege-rings">特权级</a>已经规定：陷入时保存 PC、切到更高特权、跳到入口。本课不重讲入口约定。缺口是：五级里 IF 可能缺页、EX 可能溢出、MEM 可能缺页，几件事可以挤在同一拍。本课只要求<strong>精确异常</strong>：提交点之前的指令全部完成，之后的当作没发生。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单周期里异常与当前指令同一拍，PC 就是那条指令。流水线里，MEM 的 load 缺页时，后面的 IF/ID 已经取了不该留下的指令，前面的 add 可能刚要写回。若让 IF 的对齐错优先于更早指令的缺页，软件看见的 EPC 会跳。缺口不是新的陷阱类型，而是<strong>按程序序仲裁，并在提交前冲刷年轻指令</strong>。</p><p>中断是异步的，通常挂到某条指令的提交边界，而不是卡在组合逻辑中间。本课把中断与同步异常放在同一套提交纪律下。</p><p><span class="marginnote">不精确异常曾出现在早期流水线浮点核：EPC 不能指出哪一条。操作系统和调试几乎无法接受。教学整数核必须精确。</span></p><p><span class="marginnote">「精确异常」翻译成大白话就是：异常那一刻，软件看到的现场和把指令一条条顺序执行时一模一样——异常指令之前的全部做完，之后的全部没开始。有了这个保证，操作系统才敢直接「从 EPC 那条指令重试」，而不用先弄清流水线里还塞着哪些半成品。</span></p><p><span class="marginnote">初学者容易以为：IF 段发现的取指错误会先报出来，因为它在物理时间上更早发生。实际上报告顺序按程序序排——流水线里排在前面（更年长）的指令优先，哪怕它的异常更晚才被检测到。做反了，EPC 就会指向错误的指令。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>指定 WB 前或 MEM 结束为提交点：只有到达该点的指令可以改架构状态（寄存器堆、已提交的存储）。更年轻的级一律冲刷。同一拍多处异常，选最年长的那条指令对应的原因，把 EPC 写成它的 PC。</p>',11)),(B(),s(l,null,{default:e(()=>[o(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20OLD%5B%22%E5%B9%B4%E9%95%BF%E6%8C%87%E4%BB%A4%E5%BC%82%E5%B8%B8%22%5D%20--%3E%20PICK%5B%22%E6%8C%89%E7%A8%8B%E5%BA%8F%E5%BA%8F%E9%80%89%E4%B8%80%E6%9D%A1%22%5D%0A%20%20YOUNG%5B%22%E5%B9%B4%E8%BD%BB%E6%8C%87%E4%BB%A4%E5%BC%82%E5%B8%B8%22%5D%20--%3E%20PICK%0A%20%20PICK%20--%3E%20FLUSH%5B%22%E5%86%B2%E5%88%B7%E5%B9%B4%E8%BD%BB%E7%BA%A7%22%5D%0A%20%20PICK%20--%3E%20TRAP%5B%22%E5%86%99%20EPC%EF%BC%8C%E5%88%87%E7%89%B9%E6%9D%83%EF%BC%8C%E8%B7%B3%E5%85%A5%E5%8F%A3%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"load 缺页时，该 load 本身未提交，重试时从它再取。这与误预测冲刷相同：流水线寄存器作废；不同的是接下来进入陷阱处理，而不是用户目标地址。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[n("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"精确性把「流水线内部的重叠」对软件藏起来。处理程序看见的寄存器堆，等于异常指令之前所有指令都已顺序执行完毕。转发与预测仍然存在，但它们改的是未提交状态；提交点一到，旁路值必须已经写入或被丢弃。",-1)),a[6]||(a[6]=E("p",null,"外部中断可以等当前指令提交再进陷阱，避免在 ALU 中间切开。缺页、非法指令不能推迟到后面的指令提交之后，否则软件会看见不该存在的写回。",-1)),a[7]||(a[7]=E("p",null,"换个角度问：load 在 MEM 段缺页的那一拍，流水线里每条指令各自的结局是什么？",-1)),(B(),s(l,null,{default:e(()=>[o(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22load%20%E5%9C%A8%20MEM%20%E7%BC%BA%E9%A1%B5%E8%BF%99%E4%B8%80%E6%8B%8D%22%5D%20--%3E%20WB%5B%22WB%20%E6%AE%B5%E7%9A%84%E5%B9%B4%E9%95%BF%E6%8C%87%E4%BB%A4%22%5D%0A%20%20Q%20--%3E%20SELF%5B%22%E7%BC%BA%E9%A1%B5%E7%9A%84%20load%20%E6%9C%AC%E8%BA%AB%22%5D%0A%20%20Q%20--%3E%20YOUNG%5B%22EX%2FID%2FIF%20%E6%AE%B5%E7%9A%84%E5%B9%B4%E8%BD%BB%E6%8C%87%E4%BB%A4%22%5D%0A%20%20WB%20--%3E%20R1%5B%22%E7%85%A7%E5%B8%B8%E5%86%99%E5%9B%9E%EF%BC%8C%E5%85%81%E8%AE%B8%E6%8F%90%E4%BA%A4%22%5D%0A%20%20SELF%20--%3E%20R2%5B%22%E4%B8%8D%E5%8F%91%E5%86%99%E5%9B%9E%EF%BC%8CEPC%20%E8%AE%B0%E5%AE%83%E7%9A%84%20PC%22%5D%0A%20%20YOUNG%20--%3E%20R3%5B%22%E4%BD%9C%E5%BA%9F%E6%B5%81%E6%B0%B4%E7%BA%BF%E5%AF%84%E5%AD%98%E5%99%A8%EF%BC%8C%E8%A7%86%E5%90%8C%E6%B2%A1%E5%8F%96%E8%BF%87%22%5D%0A%20%20R2%20--%3E%20R4%5B%22%E9%99%B7%E9%98%B1%E5%A4%84%E7%90%86%E5%AE%8C%E4%BB%8E%20EPC%20%E9%87%8D%E6%96%B0%E5%8F%96%E6%8C%87%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=r('<p><span class="marginnote">可以把它想象成机场安检：只有走过安检线（提交点）的乘客才算登机；还在队伍里的人（年轻指令）被直接请出队，队伍相对顺序不变。这样「谁上了飞机」永远说得清，出事时也知道该从队伍哪里重新数起。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入重排序缓冲：五级顺序流水线用固定提交点就够。<a href="/cs/ooo-rob">乱序与 ROB</a> 才在乱序执行时用 ROB 重建精确状态。也不把缺页的页表处理写成操作系统课：入口仍是特权级那一套，只是流水线保证 EPC 可信。</p><p>后课默认：谈到异常，五级核是精确的；CPI 损失包含冲刷与陷阱路径，定量在下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多条指令在飞时，异常仍按程序序只报告一条。</li><li>提交点之前完成，之后冲刷；EPC 指向该指令。</li><li>乱序下的精确性靠后课 ROB。</li><li>出处：Patterson and Hennessy, <em>COD</em> RISC-V；Hennessy and Patterson, <em>CA:AQA</em> 异常与流水线。</li></ul>',6))])}const h=i(d,[["render",C]]);export{f as __pageData,h as default};
